const CANVAS_SIZE = 1050;
const CANVAS_MERGIN = 31;

const NUM_GRID = 8;

//===

let gridSize, imgSize, img, imgMask;

let t;

let t_0, t_1, periode_0, periode_1;

choice = [];

//===

const PALETTES = [
  ["#E63946", "#F1FAEE", "#A8DADC", "#457B9D", "#1D3557"],
  ["#003049", "#D62828", "#F77F00", "#FCBF49", "#EAE2B7"],
  ["#EF476F", "#FFD166", "#06D6A0", "#118AB2", "#073B4C"],
  ["#2B2D42", "#8D99AE", "#EDF2F4", "#EF233C", "#D90429"],
  ["#3D5A80", "#98C1D9", "#E0FBFC", "#EE6C4D", "#293241"],
  ["#011627", "#FDFFFC", "#2EC4B6", "#E71D36", "#FF9F1C"],
  ["#1A535C", "#4ECDC4", "#F7FFF7", "#FF6B6B", "#FFE66D"],
  ["#F08080", "#F4978E", "#F8AD9D", "#FBC4AB", "#FFDAB9"],
  ["#03045E", "#0077B6", "#00B4D8", "#90E0EF", "#CAF0F8"],
  ["#FF595E", "#FFCA3A", "#8AC926", "#1982C4", "#6A4C93"],
  ["#50514F", "#F25F5C", "#FFE066", "#247BA0", "#70C1B3"],
  ["#390099", "#9E0059", "#FF0054", "#FF5400", "#FFBD00"],
  ["#247BA0", "#70C1B3", "#B2DBBF", "#F3FFBD", "#FF1654"],
  ["#FADDE1", "#FFC4D6", "#FFA6C1", "#FF87AB", "#FF5D8F",
   "#FF97B7", "#FFACC5", "#FFCAD4", "#F4ACB7"],
  ["#233D4D", "#FE7F2D", "#FCCA46", "#A1C181", "#619B8A"],
];

//$$$$$$$$$$$$$$$$$$$$

function setup() {
  createCanvas(CANVAS_SIZE + CANVAS_MERGIN * 2, (CANVAS_SIZE + CANVAS_MERGIN * 2)*.75);

	gridSize = int(CANVAS_SIZE / NUM_GRID);
  imgSize = gridSize * NUM_GRID;

	img = createGraphics(imgSize, imgSize);

	for (let i = 0; i < NUM_GRID; i++) {choice[i] = i }

	t = 100; // random([50, 100, 250, 500]);

	t_0 = millis();
	t_1 = millis();
	periode_0 = 10000;
	periode_1 = 200;

  drawContents();
}

//$$$$$$$$$$$$$$$$$$$$

function draw() {

	if ( millis() >= t_0 + periode_0 ) { t_0 = millis(); drawContents() }

	if ( millis() >= t_1 + periode_1 ) { t_1 = millis(); drawOneFlag() }

	image(img, CANVAS_MERGIN, CANVAS_MERGIN);

}

//$$$$$$$$$$$$$$$$$$$$

function drawContents() {

		let palette = random(PALETTES).slice();
  	shuffle(palette, true);
  	background(palette.pop());

		imgMask = createMaskImage(gridSize, gridSize);

		//===

		img.remove();
		img = createGraphics(imgSize, imgSize);	

  	img.translate((CANVAS_SIZE - imgSize) / 2, (CANVAS_SIZE - imgSize) / 2);

		for (let gy = 0; gy < NUM_GRID*.75; gy++) {
				for (let gx = 0; gx < NUM_GRID; gx++) {
					let palette = random(PALETTES).slice();
					shuffle(palette, true);
					img.push();
						img.translate(gx * gridSize, gy * gridSize);
						drawFlag(img, gridSize, gridSize, t, palette, imgMask);
					img.pop();
				}
		}  	

}

//===

function drawOneFlag () {

	let i_x = random (choice);
	let i_y = random (choice);

	let palette = random(PALETTES).slice();
	shuffle(palette, true);
	img.push();
		img.translate(i_x * gridSize, i_y * gridSize);
		drawFlag(img, gridSize, gridSize, t, palette, imgMask);
	img.pop();

}

//===	

function createMaskImage(w, h) {
  let g = createGraphics(w, h);
  let r = min(w, h) * 0.9;
  g.translate(w / 2, h / 2);
  g.rect(-w * 0.4, -h * 0.4, w * 0.8, h * 0.8);
  let imgMask = createImage(w, h);
  imgMask.copy(g, 0, 0, g.width, g.height, 0, 0, g.width, g.height);
	g.remove();
  return imgMask;
}

//===

function drawFlag(g, w, h, t, palette, imgMask) {
  let gTmp = createGraphics(w, h);
  drawPattern(gTmp, w, h, t, palette);
  let imgTmp = createImage(w, h);
  imgTmp.copy(gTmp, 0, 0, w, h, 0, 0, w, h);
  imgTmp.mask(imgMask);
  g.image(imgTmp, 0, 0, w, h);
	gTmp.remove();

  g.push();
		g.noFill();
		var scribble = new Scribble(g);
		scribble.scribbleRect(w / 2, h / 2, w * 0.8, h * 0.8);
	g.pop();
}

//===

// https://openprocessing.org/sketch/1278485
function drawPattern(g, w, h, t, palette) {
  g.pattern(randPattern(t));
  g.patternColors(palette);
  g.patternAngle((int(random(4)) * PI) / 4);
  g.rectPattern(0, 0, w, h);
}

// https://openprocessing.org/sketch/1278485
function randPattern(t) {
  const ptArr = [
    PTN.noise(0.5),
    PTN.noiseGrad(0.4),
    PTN.stripe(t / int(random(6, 12))),
    PTN.stripeCircle(t / int(random(6, 12))),
    PTN.stripePolygon(int(random(3, 7)), int(random(6, 12))),
    PTN.stripeRadial(TAU / int(random(6, 30))),
    PTN.wave(t / int(random(1, 3)), t / int(random(10, 20)), t / 5, t / 10),
    PTN.dot(t / 10, (t / 10) * random(0.2, 1)),
    PTN.checked(t / int(random(5, 20)), t / int(random(5, 20))),
    PTN.cross(t / int(random(10, 20)), t / int(random(20, 40))),
    PTN.triangle(t / int(random(5, 20)), t / int(random(5, 20))),
  ];
  return random(ptArr);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}
